import math

def build_instance(rng):
    length = rng.randint(1, 10)
    slope = rng.randint(-10, 10)
    gcd = math.gcd(length, slope)
    answer = length // gcd + 1
    check = 0
    for x in range(length + 1):
        y = slope / length * x
        if y.is_integer():
            check += 1
    parameters = {'length': length, 'slope': slope}
    return (parameters, answer, check)



