def build_instance(rng):
    radius = rng.randint(1, 10)
    slope = rng.randint(-10, 10)
    y_intercept = rng.randint(-10, 10)
    x = sympy.symbols('x', integer=True)
    y = slope * x + y_intercept
    circle_eq = x ** 2 + y ** 2 - radius ** 2
    line_eq = y - (slope * x + y_intercept)
    solutions = sympy.solve([circle_eq, line_eq], (x, y))
    answer = len(solutions)
    check = sum((1 for sol in solutions if sol[0].is_integer and sol[1].is_integer))
    parameters = {'radius': radius, 'slope': slope, 'y_intercept': y_intercept}
    return (parameters, answer, check)



