def build_instance(rng):
    degree = rng.randint(1, 5)
    coefficients = [rng.randint(-10, 10) for _ in range(degree + 1)]
    x = sympy.symbols('x', integer=True)
    polynomial = sum((coeff * x ** i for i, coeff in enumerate(coefficients)))
    value = rng.randint(1, 10)
    answer = polynomial.subs(x, value)
    check = sum((coeff * value ** i for i, coeff in enumerate(coefficients)))
    parameters = {'degree': degree, 'value': value}
    return (parameters, answer, check)



