import math

def build_instance(rng):
    vertex_count = rng.randint(3, 10)
    total_triangles = math.comb(vertex_count, 3)
    favorable_triangles = vertex_count * (vertex_count - 1)
    answer = favorable_triangles / total_triangles
    check = 0
    for i in range(vertex_count):
        for j in range(i + 1, vertex_count):
            for k in range(j + 1, vertex_count):
                if (i == j or j == k or k == i) or (i == (j + 1) % vertex_count or j == (k + 1) % vertex_count or k == (i + 1) % vertex_count):
                    check += 1
    assert answer == check / total_triangles, f'answer={answer} check={check}'
    parameters = {'vertex_count': vertex_count}
    return (parameters, answer, check)



