    constant = rng.randint(1, 100)
    x = sympy.symbols('x', integer=True)
    y = sympy.symbols('y', integer=True)
    equation = sympy.Eq(3 * x + 4 * y, constant)
    solutions = sympy.solve(equation, (x, y), dict=True)
    answer = len([sol for sol in solutions if sol[x] >= 0 and sol[y] >= 0])
    check = 0
    for x_val in range(constant // 3 + 1):
        y_val = (constant - 3 * x_val) / 4
        if y_val.is_integer() and y_val >= 0:
            check += 1
    parameters = {'constant': constant}
    return (parameters, answer, check)



