import sympy
import fractions
import itertools

def build_instance(rng):
    value_at_zero = rng.randint(-10, 10)
    value_at_one = rng.randint(-10, 10)
    value_at_two = rng.randint(-10, 10)
    a, b, c = sympy.symbols('a b c')
    eq1 = sympy.Eq(c, value_at_zero)
    eq2 = sympy.Eq(a + b + c, value_at_one)
    eq3 = sympy.Eq(4 * a + 2 * b + c, value_at_two)
    solution = sympy.solve((eq1, eq2, eq3), (a, b, c))
    a_val = solution[a]
    b_val = solution[b]
    c_val = solution[c]
    P_3 = 9 * a_val + 3 * b_val + c_val
    P_3_simplified = fractions.Fraction(P_3).limit_denominator()
    answer = str(P_3_simplified)
    P = a_val * sympy.Symbol('x') ** 2 + b_val * sympy.Symbol('x') + c_val
    P_3_check = P.subs(sympy.Symbol('x'), 3)
    check = str(P_3_check)
