import sympy

def build_instance(rng):
    vertex_count = rng.randint(2, 10)
    vertex_degree = rng.randint(1, vertex_count - 1)
    if vertex_count == 2 and vertex_degree == 1:
        answer = 1
    elif vertex_count == 3 and vertex_degree == 1:
        answer = 3
    elif vertex_count == 3 and vertex_degree == 2:
        answer = 1
    else:
        answer = sympy.binomial(vertex_count, vertex_degree) * sympy.binomial(vertex_count - 1, vertex_degree - 1)
    check = 0
    for i in range(2 ** (vertex_count * (vertex_count - 1) // 2)):
        graph = [[0] * vertex_count for _ in range(vertex_count)]
        for j in range(vertex_count * (vertex_count - 1) // 2):
            if i >> j & 1:
                graph[j // vertex_count][j % vertex_count] = 1
                graph[j % vertex_count][j // vertex_count] = 1
        degree = [sum(graph[i]) for i in range(vertex_count)]
        if all((degree[i] == vertex_degree for i in range(vertex_count))):
            check += 1
    parameters = {'vertex_count': vertex_count, 'vertex_degree': vertex_degree}
